import { Logout } from '@mesx/common-ui-lib';
import { createRouter, createWebHistory } from 'vue-router';
import { useProfileStore } from '@/Auth/store/user-auth-store';
import loadingComponent from '@/global-components/reusable/loading-component.vue';
import unauthorized from '@/global-components/reusable/unauthorized-component.vue';
import jobScheduler from '@/modules/job-scheduler/components/job-scheduler.vue';
import appLogger from '@/utils/logger/app-logger.ts';

const appRedirectUri = import.meta.env.APP_REDIRECT_URI;
let appBasePath: string | undefined;
if (appRedirectUri) {
  const parts = appRedirectUri.split('/');
  appBasePath = parts.pop();
}

const routes = [
  {
    component: Logout,
    name: 'Logout',
    path: '/logout',
    props: {
      onLoginAgain: (): void => {
        const profileStore = useProfileStore();
        profileStore.initializeAuthentication();
      },
    },
  },
  {
    component: unauthorized,
    name: 'Unauthorized',
    path: '/job-ui/unauthorized',
  },
  {
    component: loadingComponent,
    name: 'LoadingComponent',
    path: '/loading',
  },
  {
    meta: { requiresAuth: true, title: 'Scheduler Monitoring' },
    component: jobScheduler,
    name: 'job-ui',
    path: '/job-ui',
  },
];

const router = createRouter({
  history: createWebHistory(),
  routes,
});

router.beforeEach(async (to, _from, next) => {
  if (to.meta.title) {
    document.title = `MESX.0 - ${to.meta.title as string}`;
  }

  const userAuth = useProfileStore();

  if (to.meta.requiresAuth) {
    try {
      await userAuth.authenticateUser();
      const user = await userAuth.getUser();
      if (user) {
        await userAuth.fetchUserAttributes();
        await userAuth.authorizeUser();
      } else {
        console.error('User not found');
        return next(`/${appBasePath}/unauthorized`);
      }
      return next();
    } catch (error) {
      appLogger.error(`Error during authentication or authorization: ${error}`);
      return next(`/${appBasePath}/unauthorized`);
    }
  }

  return next();
});

