const jobSchedulerApiClient = axios.create({
  baseURL: import.meta.env.JOB_SCHEDULER_BACKEND_URL,
  headers: {
    authorization: `Bearer ${import.meta.env.TOKEN}`,
  },
});

export class JobScheduler {
  private readonly notify: Notify | undefined;

  public constructor(notify?: Notify) {
    if (notify) {
      // â Use the provided instance
      this.notify = notify;
    } else {
      // â Try to get it from Vueâs injection system
      const notifyInstance = inject<Notify>('notify');
      if (notifyInstance) {
        this.notify = notifyInstance;
      } else {
        console.warn(
          '[JobScheduler] No Notify instance provided or found via inject().',
        );
      }
    }
  }

  public async getAllJobs(): Promise<Array<JobResponse> | undefined> {
    try {
      const response: AxiosResponse<Array<JobResponse>> =
        await jobSchedulerApiClient.get('/jobs');
      return response.data;
    } catch {
      this.notify?.error({
        title: 'API Error',
        message: 'Error while fetching jobs',
      });
      return undefined;
    }
  }

  public async getJobById(jobId: string): Promise<JobResponse | undefined> {
    try {
      const response: AxiosResponse<JobResponse> =
        await jobSchedulerApiClient.get(`/jobs/${jobId}`);
      return response.data;
    } catch {
      this.notify?.error({
        title: 'API Error',
        message: 'Error while creating the job',
      });
      return undefined;
    }
  }

  public async createJob(
    createDto: CreateJobDto,
  ): Promise<JobResponse | undefined> {
    try {
      const response: AxiosResponse<JobResponse> =
        await jobSchedulerApiClient.post('/jobs', createDto);
      return response.data;
    } catch {
      this.notify?.error({
        title: 'API Error',
        message: 'Erreur lors de la crÃ©ation du job',
      });
      return undefined;
    }
  }

  public async updateJob(
    jobId: string,
    updateDto: UpdateJobDto,
  ): Promise<JobResponse | undefined> {
    try {
      const response: AxiosResponse<JobResponse> =
        await jobSchedulerApiClient.patch(`/jobs/${jobId}`, updateDto);
      return response.data;
    } catch {
      this.notify?.error({
        title: 'API Error',
        message: `Error while updating job ${jobId}`,
      });
      return undefined;
    }
  }

  public async updateJobPlantConfig(
    jobId: string,
    plantId: number,
    plantConfig: PlantUpdateDto,
  ): Promise<JobResponse | undefined> {
    try {
      const response: AxiosResponse<JobResponse> =
        await jobSchedulerApiClient.patch(
          `/jobs/${jobId}/plant/${plantId}`,
          plantConfig,
        );
      return response.data;
    } catch {
      this.notify?.error({
        title: 'API Error',
        message: `Error while updating the configuration of plant ${plantId} for job ${jobId}`,
      });
      return undefined;
    }
  }

  public async deleteJob(jobId: string): Promise<void> {
    try {
      await jobSchedulerApiClient.delete(`/jobs/${jobId}`);
    } catch {
      this.notify?.error({
        title: 'API Error',
        message: `Error while deleting job ${jobId}`,
      });
    }
  }

  public async deletePlantFromJob(
    jobId: string,
    plantId: string,
  ): Promise<JobResponse | undefined> {
    try {
      const response: AxiosResponse<JobResponse> =
        await jobSchedulerApiClient.delete(`/jobs/${jobId}/plant/${plantId}`);
      this.notify?.success({
        message: 'Selected jobs were successfully deleted from their plants.',
        title: 'Action Successful',
      });
      return response.data;
    } catch (error) {
      const axiosError = error as AxiosError<{ message?: string }>;

      const errorMessage =
        axiosError.response?.data?.message ??
        axiosError.message ??
        'Unknown error';

      this.notify?.error({
        title: 'Action Blocked',
        message: `Failed to deactivate job ${jobId}: ${errorMessage}`,
      });

      return undefined;
    }
  }

  public async activateJobPlants(
    jobId: string,
    activateDto: PlantJobActivateDto,
  ): Promise<JobResponse | undefined> {
    try {
      const response: AxiosResponse<JobResponse> =
        await jobSchedulerApiClient.post(
          `/jobs/${jobId}/activate`,
          activateDto,
        );
      if (activateDto.plantIds) {
        this.notify?.success({
          message: `Job ${jobId} has been activated for plants: ${activateDto.plantIds.join(', ')}`,
          title: 'Job Activated',
        });
      }

      return response.data;
    } catch {
      this.notify?.error({
        message: `Error while activating job ${jobId}`,
        title: 'API Error',
      });
      return undefined;
    }
  }

  public async stopJobPlant(
    jobId: string,
    plantId: number,
  ): Promise<JobResponse | undefined> {
    try {
      const response: AxiosResponse<JobResponse> =
        await jobSchedulerApiClient.post(
          `/jobs/${jobId}/plant/${plantId}/stop`,
        );
      return response.data;
    } catch {
      this.notify?.error({
        title: 'API Error',
        message: `Error while stopping job ${jobId} for plant ${plantId}`,
