      return undefined;
    }
  }

  public async deactivateJobPlants(
    jobId: string,
    deactivateDto: PlantJobActivateDto,
  ): Promise<JobResponse | undefined> {
    try {
      const response: AxiosResponse<JobResponse> =
        await jobSchedulerApiClient.post(
          `/jobs/${jobId}/deactivate`,
          deactivateDto,
        );

      if (deactivateDto.plantIds?.length) {
        this.notify?.success({
          title: 'Job Deactivated',
          message: `Job ${jobId} has been deactivated for plants: ${deactivateDto.plantIds.join(', ')}`,
        });
      }

      return response.data;
    } catch (error) {
      const axiosError = error as AxiosError<{ message?: string }>;

      const errorMessage =
        axiosError.response?.data?.message ??
        axiosError.message ??
        'Unknown error';

      this.notify?.error({
        title: 'API Error',
        message: `Failed to deactivate job ${jobId}: ${errorMessage}`,
      });

      return undefined;
    }
  }

  public async rescheduleJob(
    jobId: string,
    rescheduleDto: RescheduleJobDto,
  ): Promise<JobResponse | undefined> {
    try {
      const response: AxiosResponse<JobResponse> =
        await jobSchedulerApiClient.post(
          `/jobs/${jobId}/reschedule`,
          rescheduleDto,
        );
      this.notify?.success({
        title: 'Job update',
        message: `this job ${jobId}has been updated successfully.  `,
      });
      return response.data;
    } catch {
      this.notify?.error({
        title: 'API Error',
        message: `Error while rescheduling the job ${jobId}`,
      });
      return undefined;
    }
  }

  public async executeJobImmediately(
    jobId: string,
    executeDto: PlantJobActivateDto,
  ): Promise<JobResponse | undefined> {
    try {
      const response: AxiosResponse<JobResponse> =
        await jobSchedulerApiClient.post(`/jobs/${jobId}/execute`, executeDto);
      return response.data;
    } catch {
      this.notify?.error({
        title: 'API Error',
        message: `Error while executing the job immediately${jobId}`,
      });
      return undefined;
    }
  }

  public async getPlantJobHistory(
    jobId: string,
    plantId: number,
    limit?: number,
  ): Promise<Array<JobExecutionHistory> | undefined> {
    try {
      // Construct query params
      const parameters = limit ? { limit } : {};

      // Make GET request
      const response: AxiosResponse<Array<JobExecutionHistory>> =
        await jobSchedulerApiClient.get(
          `/jobs/${jobId}/plant/${plantId}/history`,
          { params: parameters },
        );
      return response.data;
    } catch {
      // Show error notification
      this.notify?.error({
        title: 'API Error',
        message: `Failed to load execution history for job ${jobId} and plant ${plantId}.`,
      });
      return undefined;
    }
  }

  public async getPlants(): Promise<
    Array<PlantIngestionResponseDto> | undefined
  > {
    try {
      // Construct query params
      // Make GET request
      const response: AxiosResponse<Array<PlantIngestionResponseDto>> =
        await jobSchedulerApiClient.get(`/jobs/plants`);

      // Optionally show success notification
      return response.data;
    } catch {
      // Show error notification
      this.notify?.error({
        title: 'API Error',
        message: `Failed fetch Plant data`,
      });
      return undefined;
    }
  }

  public async addPlantToJob(
    jobId: string,
    plantConfig: PlantConfig,
  ): Promise<void> {
    try {
      await jobSchedulerApiClient.post(`/jobs/${jobId}/plant`, plantConfig);
      this.notify?.success({
        title: 'Success',
        message: `Plant ${plantConfig.id} added to job ${jobId} successfully.`,
      });
    } catch {
      // Show error notification
      this.notify?.error({
        title: 'API Error',
        message: `Failed add plant to the job ${jobId} `,
      });
    }
  }
}

import { defineStore } from 'pinia';
import { QTableColumn } from 'quasar';
import { ref } from 'vue';
import type { JobResponse } from '@/modules/job-scheduler/interfaces/job-response.type';
import { JobScheduler } from '@/modules/job-scheduler/services/job-scheduler';
import type { Notify } from '@/types/notify';

interface SelectedJob {
  jobId: string;
  plantId: string;
  status: string;
}

export const useJobSchedulerStore = defineStore({
  id: 'jobSchedulerStore',

  state: () => ({
    columns: [
      {
        align: 'left',
        field: 'id',
        label: 'SERVICE NAME',
        name: 'id',
        style: 'width: 120px',
      },
      { align: 'left', field: 'name', label: 'JOB NAME', name: 'name' },
      {
        align: 'left',
        field: 'description',
        label: 'DESCRIPTION',
        name: 'description',
      },
      { align: 'left', field: 'pattern', label: 'PATTERN', name: 'pattern' },
      {
        align: 'left',
        field: 'status',
        label: 'STATUS',
        name: 'status',
        style: 'width: 100px',
      },
    ] as Array<QTableColumn>,
    expandedRows: [] as Array<string>,
    jobs: [] as Array<JobResponse>,
    loading: ref(false),
    notify: undefined as Notify | undefined, // ð store notify instance safely
    selectedJobs: [] as Array<SelectedJob>,
  }),

  getters: {
    groupedJobs: (state) => {
      const result: Record<string, Array<string>> = {};
      for (const { jobId, plantId } of state.selectedJobs) {
        if (!result[jobId]) result[jobId] = [];
        result[jobId].push(plantId);
      }
      return result;
    },
  },

  actions: {
    // â Call this once in your component after injecting `notify`
    setNotify(notify: Notify) {
      this.notify = notify;
    },

    async fetchJobs() {
      const jobScheduler = new JobScheduler(this.notify);
      this.loading = true;
      try {
        const response = await jobScheduler.getAllJobs();
        if (response) {
          this.jobs = response;
        }
      } catch (error) {
        this.notify?.error({
          title: 'Failed to Fetch Jobs',
          message: error instanceof Error ? error.message : String(error),
        });
      } finally {
        this.loading = false;
      }
    },

    async executeJobImmediately() {
      const jobScheduler = new JobScheduler(this.notify);
      try {
        const promises = Object.entries(this.groupedJobs).map(
          ([jobId, plantIds]) =>
            jobScheduler.executeJobImmediately(jobId, { plantIds }),
        );
        await Promise.all(promises);
        this.notify?.success({
          message: `The job  was executed successfully.`,
          title: 'Job Executed',
        });
      } catch (error) {
        this.notify?.error({
          title: 'Execution Failed',
          message: error instanceof Error ? error.message : String(error),
        });
      }
    },

    async startJob() {
      const jobScheduler = new JobScheduler(this.notify);
      try {
        const promises = Object.entries(this.groupedJobs).map(
          ([jobId, plantIds]) =>
            jobScheduler.activateJobPlants(jobId, { plantIds }),
        );
        await Promise.all(promises);
        await this.fetchJobs();
        this.clearSelectedJobs();
      } catch (error) {
        this.notify?.error({
          title: 'Start Failed',
          message: error instanceof Error ? error.message : String(error),
        });
      }
    },

    async stopJob() {
      const jobScheduler = new JobScheduler(this.notify);
      try {
        const promises = Object.entries(this.groupedJobs).map(
          ([jobId, plantIds]) =>
            jobScheduler.deactivateJobPlants(jobId, { plantIds }),
        );
        await Promise.all(promises);
        await this.fetchJobs();
        this.clearSelectedJobs();
      } catch (error) {
        this.notify?.error({
          title: 'Stop Failed',
          message: error instanceof Error ? error.message : String(error),
        });
      }
    },

    async deleteJobs() {
      const jobScheduler = new JobScheduler(this.notify);
      try {
        const promises = Object.entries(this.groupedJobs).flatMap(
          ([jobId, plantIds]) =>
            plantIds.map((plantId) =>
              jobScheduler.deletePlantFromJob(jobId, plantId),
            ),
        );
        await Promise.all(promises);
        await this.fetchJobs();
        this.clearSelectedJobs();
        this.notify?.success({
          title: 'Jobs Deleted',
          message: 'Selected jobs have been deleted successfully',
        });
      } catch (error) {
        this.notify?.error({
          title: 'Delete Failed',
          message: error instanceof Error ? error.message : String(error),
        });
      }
    },

    clearSelectedJobs() {
      this.selectedJobs = [];
    },
    clearSelection() {
      this.selectedJobs = [];
      this.expandedRows = [];
    },
  },
});

